"""Reviewed Chinese for the labels and boilerplate a Handbook page is made of.

Why this file exists
--------------------
The offline translator is good at the shape of a sentence and bad at the words
a degree page is built from. On the live site it rendered *Breadth studies* as
面包研究 (bakery studies), *Robotics and mechatronics engineering* as 机器人和中程器工程
(and, in other sentences of the same page, 中子医学, 中医药学 and 中杂技), *Curating*
as 惩罚 (punishment), a *stream* as 溪流 (a brook) or 流 (a flow), a *Department*
as 系： and a *gateway unit* as 网关课程. None of that is fixable by asking the
model again: it gave a different wrong answer for the same phrase in every
sentence.

So every distinct short string that appears in the structure of a course or an
area of study, and the stock sentences the Handbook repeats across units (how a
unit is taught, how it is assessed, what a "Part B" is), was read against its
English and given one wording. They are keyed by the **exact** English string.
A string that is not here still goes to the translator, which is the same
behaviour as before; a string that is here never does.

Conventions, so the next entry agrees with the last
---------------------------------------------------
* *unit* is 课程 and *course* is 学位课程 (see ``glossary.py``); *stream* is 方向,
  *component* is 部分, *discipline* is 学科, *pathway* is 路径, *studies* in a
  requirement group is 课程 (a discipline's own name keeps 研究/学),
  *Part B.* is ``B 部分。``, *Breadth studies* is 通识课程（Breadth studies）.
* Campuses keep their English name plus 校区, programme and institute names stay
  English where students meet them in English, and partner universities take
  their usual Chinese name.
* A sentence tells the student what they must do, so it is written in the second
  person ("你必须完成…") and never as 您 in one place and 你 in another.

How it is used
--------------
``seed.py`` publishes this as part of the human ``global/handbook`` row, so on
read it beats the machine's rendering on every course, area of study and unit.
``crawler/translate/engine.py`` consults it before the model, line by line, so
the next Handbook year starts from these wordings instead of rediscovering the
mistakes. Degree *names* are not here: they are built by ``degrees.py``.

Written by an AI assistant at the maintainer's direction and checked against the
English only - it has not been read by a native-speaking reviewer, and the
``note`` on the seeded row says so. Corrections are pull requests to this file.
"""
